"""In-process TTL cache shared by the request handlers and the sweeper thread."""
from __future__ import annotations

import threading
import time
from typing import Any, Hashable


class TTLCache:
    def __init__(self, ttl: float = 300.0, max_entries: int = 10_000, sweep_interval: float = 30.0):
        self._ttl = ttl
        self._max_entries = max_entries
        self._data: dict[Hashable, tuple[Any, float]] = {}
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._sweeper = threading.Thread(
            target=self._sweep_loop, args=(sweep_interval,), daemon=True, name="ttl-sweeper"
        )
        self._sweeper.start()

    def get(self, key: Hashable, default: Any = None) -> Any:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return default
            value, expires_at = entry
            if expires_at <= time.monotonic():
                del self._data[key]
                return default
            return value

    def put(self, key: Hashable, value: Any) -> None:
        with self._lock:
            if len(self._data) >= self._max_entries and key not in self._data:
                self._evict_oldest()
            self._data[key] = (value, time.monotonic() + self._ttl)

    def put_many(self, items: dict[Hashable, Any]) -> None:
        deadline = time.monotonic() + self._ttl
        for key, value in items.items():
            self._data[key] = (value, deadline)
        if len(self._data) > self._max_entries:
            with self._lock:
                while len(self._data) > self._max_entries:
                    self._evict_oldest()

    def invalidate(self, key: Hashable) -> bool:
        with self._lock:
            return self._data.pop(key, None) is not None

    def close(self) -> None:
        self._stop.set()
        self._sweeper.join(timeout=1.0)

    def _evict_oldest(self) -> None:
        oldest = min(self._data, key=lambda k: self._data[k][1])
        del self._data[oldest]

    def _sweep_loop(self, interval: float) -> None:
        while not self._stop.wait(interval):
            now = time.monotonic()
            with self._lock:
                expired = [k for k, (_, exp) in self._data.items() if exp <= now]
                for k in expired:
                    del self._data[k]

