"""Session store backing the login middleware."""
import secrets
import threading
import time

SESSION_TTL = 3600
MAX_SESSIONS = 5000


class SessionStore:
    def __init__(self, ttl=SESSION_TTL, clock=time.time):
        self._ttl = ttl
        self._clock = clock
        self._sessions = {}
        self._lock = threading.RLock()

    def create(self, user_id, ip):
        token = secrets.token_urlsafe(32)
        now = self._clock()
        with self._lock:
            self._evict_expired(now)
            if len(self._sessions) >= MAX_SESSIONS:
                self._drop_oldest()
            self._sessions[token] = {
                "user_id": user_id,
                "ip": ip,
                "created": now,
                "last_seen": now,
            }
        return token

    def get(self, token):
        now = self._clock()
        with self._lock:
            self._evict_expired(now)
            session = self._sessions.get(token)
            if session is None:
                return None
            session["last_seen"] = now
            return dict(session)

    def revoke(self, token):
        with self._lock:
            return self._sessions.pop(token, None) is not None

    def revoke_user(self, user_id):
        with self._lock:
            doomed = [t for t, s in self._sessions.items() if s["user_id"] == user_id]
            for token in doomed:
                del self._sessions[token]
            return len(doomed)

    def count(self):
        with self._lock:
            return len(self._sessions)

    def _evict_expired(self, now):
        cutoff = now - self._ttl
        stale = [t for t, s in self._sessions.items() if s["last_seen"] < cutoff]
        for token in stale:
            del self._sessions[token]

    def _drop_oldest(self):
        oldest = min(self._sessions, key=lambda t: self._sessions[t]["created"])
        del self._sessions[oldest]

