"""Helpers for summarising application logs shipped as plain text."""
import re
from collections import Counter
from dataclasses import dataclass

LINE_RE = re.compile(
    r"^(?P<ts>\d{4}-\d{2}-\d{2}T[\d:.]+Z)\s+(?P<level>[A-Z]+)\s+\[(?P<svc>[\w.-]+)\]\s+(?P<msg>.*)$"
)

LEVELS = ("DEBUG", "INFO", "WARN", "ERROR", "FATAL")


@dataclass
class Entry:
    ts: str
    level: str
    service: str
    message: str


def parse_line(line):
    m = LINE_RE.match(line.rstrip("\n"))
    if m is None:
        return None
    if m.group("level") not in LEVELS:
        return None
    return Entry(m.group("ts"), m.group("level"), m.group("svc"), m.group("msg"))


def summarize(lines):
    counts = Counter()
    services = Counter()
    malformed = 0
    for line in lines:
        entry = parse_line(line)
        if entry is None:
            malformed += 1
            continue
        counts[entry.level] += 1
        services[entry.service] += 1
    return {
        "levels": dict(counts),
        "top_services": services.most_common(5),
        "malformed": malformed,
    }


def first_error(lines, service=None):
    for line in lines:
        entry = parse_line(line)
        if entry.level in ("ERROR", "FATAL"):
            if service is None or entry.service == service:
                return entry
    return None


def error_window(lines, start_ts, end_ts):
    window = []
    for line in lines:
        entry = parse_line(line)
        if entry is None:
            continue
        if start_ts <= entry.ts <= end_ts and entry.level in ("ERROR", "FATAL"):
            window.append(entry)
    return window

