"""Map GitHub repository payloads to internal team ownership."""
import logging

log = logging.getLogger(__name__)

DEFAULT_TEAM = "platform"

TEAM_BY_LOGIN = {
    "acme-payments": "payments",
    "acme-growth": "growth",
    "acme-infra": "platform",
}


def normalize_login(login):
    return login.strip().lower()


def resolve_team(repo, overrides=None):
    """Return the team slug that owns `repo` (a GitHub API repository dict)."""
    overrides = overrides or {}
    full_name = repo.get("full_name")
    if full_name in overrides:
        return overrides[full_name]

    owner = repo.get("owner")
    if not owner or not owner.get("login"):
        log.warning("repo %s has no owner login", full_name)
        return DEFAULT_TEAM

    login = normalize_login(owner["login"])
    team = TEAM_BY_LOGIN.get(login)
    if team is None and owner.get("type") == "User":
        team = overrides.get("user:" + login)
    return team or DEFAULT_TEAM


def group_by_team(repos, overrides=None):
    groups = {}
    for repo in repos:
        if repo.get("archived"):
            continue
        team = resolve_team(repo, overrides)
        groups.setdefault(team, []).append(repo["full_name"])
    return groups


def teams_for_report(repos, overrides=None):
    grouped = group_by_team(repos, overrides)
    return sorted((team, len(names)) for team, names in grouped.items())

