"""HTTP handlers for the invoicing API (framework adapter lives in app.py)."""
import json
import logging

from .errors import ApiError, error_response
from .ledger import Ledger

log = logging.getLogger(__name__)

MAX_CENTS = 1_000_000_000
SUPPORTED_CURRENCIES = {"USD", "EUR", "GBP", "NOK"}


def parse_amount(raw):
    """Parse an amount in integer cents (the API contract forbids fractional cents)."""
    cents = int(raw)
    if cents <= 0:
        raise ValueError("amount must be positive")
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds limit")
    return cents


def parse_currency(raw):
    code = (raw or "").upper()
    if code not in SUPPORTED_CURRENCIES:
        raise ValueError(f"unsupported currency {code!r}")
    return code


def create_charge(ledger: Ledger, body: bytes, account_id: str):
    try:
        payload = json.loads(body)
        amount = parse_amount(payload["amount"])
        currency = parse_currency(payload.get("currency", "USD"))
    except (KeyError, TypeError, json.JSONDecodeError):
        return error_response(400, "malformed request body")
    except (ValueError, OverflowError) as exc:
        return error_response(422, str(exc))

    try:
        charge = ledger.record(account_id, amount, currency)
    except ApiError as exc:
        log.warning("charge rejected for %s: %s", account_id, exc)
        return error_response(exc.status, exc.message)
    return {
        "status": 201,
        "body": {"id": charge.id, "amount": amount, "currency": currency},
    }


def refund_charge(ledger: Ledger, charge_id: str, account_id: str):
    try:
        refund = ledger.refund(account_id, charge_id)
    except ApiError as exc:
        return error_response(exc.status, exc.message)
    return {"status": 200, "body": {"id": refund.id, "charge": charge_id}}

