"""Permission bit flags carried by API tokens."""
import time

READ = 0x01
WRITE = 0x02
DELETE = 0x04
ADMIN = 0x08
BILLING = 0x10

ROLE_MASKS = {
    "viewer": READ,
    "editor": READ | WRITE,
    "owner": READ | WRITE | DELETE | BILLING,
    "root": READ | WRITE | DELETE | ADMIN | BILLING,
}


def mask_for(role):
    try:
        return ROLE_MASKS[role]
    except KeyError:
        raise ValueError(f"unknown role: {role!r}") from None


def has_perm(flags, wanted):
    """True when every bit in `wanted` is present in `flags`."""
    return flags & wanted == wanted


class Token:
    __slots__ = ("subject", "flags", "expires")

    def __init__(self, subject, flags, expires):
        self.subject = subject
        self.flags = flags
        self.expires = expires

    @classmethod
    def for_role(cls, subject, role, ttl=3600):
        return cls(subject, mask_for(role), time.time() + ttl)

    def expired(self, now=None):
        return (now or time.time()) >= self.expires

    def allows(self, *perms):
        wanted = 0
        for p in perms:
            wanted |= p
        return has_perm(self.flags, wanted)


def require(token, *perms):
    if token.expired():
        raise PermissionError(f"token for {token.subject} has expired")
    if not token.allows(*perms):
        raise PermissionError(f"{token.subject} lacks required permissions")

