"""Upload/download endpoints for user attachments."""
import hashlib
import mimetypes
import os

UPLOAD_DIR = os.environ.get("UPLOAD_DIR", "/var/lib/app/uploads")
MAX_BYTES = 25 * 1024 * 1024


class UploadError(Exception):
    pass


def _target(user_id, name):
    safe = os.path.basename(name)
    if not safe or safe.startswith("."):
        raise UploadError("invalid file name")
    return os.path.join(UPLOAD_DIR, str(user_id), safe)


def save_upload(user_id, name, stream):
    path = _target(user_id, name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    digest = hashlib.sha256()
    written = 0
    with open(path, "wb") as out:
        for chunk in iter(lambda: stream.read(64 * 1024), b""):
            written += len(chunk)
            if written > MAX_BYTES:
                out.close()
                os.unlink(path)
                raise UploadError("file too large")
            digest.update(chunk)
            out.write(chunk)
    return {"path": path, "sha256": digest.hexdigest(), "size": written}


def handle_download(request, user_id):
    name = request.args.get("name")
    if not name:
        return 400, {}, b"missing name"
    path = os.path.join(UPLOAD_DIR, str(user_id), name)
    if not os.path.isfile(path):
        return 404, {}, b"not found"
    ctype = mimetypes.guess_type(path)[0] or "application/octet-stream"
    with open(path, "rb") as fh:
        return 200, {"Content-Type": ctype}, fh.read()


def handle_delete(request, user_id):
    path = _target(user_id, request.args.get("name", ""))
    try:
        os.unlink(path)
    except FileNotFoundError:
        return 404, {}, b"not found"
    return 204, {}, b""

