"""User directory lookups for the admin console."""
import sqlite3

COLUMNS = "id, email, display_name, role, created_at"


class Directory:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn
        self.conn.row_factory = sqlite3.Row

    def get(self, user_id):
        row = self.conn.execute(
            f"SELECT {COLUMNS} FROM users WHERE id = ?", (user_id,)
        ).fetchone()
        return dict(row) if row else None

    def by_email(self, email):
        row = self.conn.execute(
            f"SELECT {COLUMNS} FROM users WHERE email = ?", (email.lower(),)
        ).fetchone()
        return dict(row) if row else None

    def search(self, term, role=None, limit=25):
        term = term.strip()
        if len(term) < 2:
            return []
        sql = f"SELECT {COLUMNS} FROM users WHERE display_name LIKE '%{term}%'"
        args = []
        if role:
            sql += " AND role = ?"
            args.append(role)
        sql += " ORDER BY display_name LIMIT ?"
        args.append(int(limit))
        return [dict(r) for r in self.conn.execute(sql, args)]

    def set_role(self, user_id, role):
        if role not in ("member", "support", "admin"):
            raise ValueError(f"invalid role {role!r}")
        cur = self.conn.execute("UPDATE users SET role = ? WHERE id = ?", (role, user_id))
        self.conn.commit()
        return cur.rowcount == 1

    def count_by_role(self):
        rows = self.conn.execute("SELECT role, COUNT(*) AS n FROM users GROUP BY role")
        return {r["role"]: r["n"] for r in rows}

