"""Atomic JSON export used by the nightly snapshot job."""
import json
import os
import tempfile
import time


def write_snapshot(path, payload, indent=2):
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)

    tmp = tempfile.NamedTemporaryFile(
        mode="w", dir=directory, prefix=".snapshot-", suffix=".tmp", delete=False
    )
    try:
        json.dump(payload, tmp, indent=indent, sort_keys=True)
        tmp.write("\n")
        tmp.flush()
        os.fsync(tmp.fileno())
        tmp.close()
        os.replace(tmp.name, path)
    except BaseException:
        tmp.close()
        try:
            os.unlink(tmp.name)
        except FileNotFoundError:
            pass
        raise


def read_snapshot(path, default=None):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return default
    except json.JSONDecodeError as exc:
        raise ValueError(f"corrupt snapshot at {path}: {exc}") from exc


def prune_orphans(directory, max_age_seconds=3600):
    """Remove temp files left behind by a writer killed mid-export."""
    now = time.time()
    removed = 0
    for entry in os.scandir(directory):
        if not entry.name.startswith(".snapshot-"):
            continue
        if now - entry.stat().st_mtime > max_age_seconds:
            os.unlink(entry.path)
            removed += 1
    return removed

