"""Query-string filter parsing for the list endpoints."""
from datetime import datetime

ALLOWED_FILTERS = {
    "projects": ("owner", "state", "label", "created_after"),
    "tickets": ("assignee", "state", "priority", "created_after"),
}
STATES = ("open", "closed", "all")


class FilterError(ValueError):
    pass


def _coerce(key, raw):
    if key == "created_after":
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            raise FilterError(f"bad timestamp for {key}: {raw!r}") from None
    if key == "state" and raw not in STATES:
        raise FilterError(f"state must be one of {', '.join(STATES)}")
    return raw


def collect_filters(params, resource, filters=[]):
    """Turn request query params into a list of (field, value) pairs."""
    for key in ALLOWED_FILTERS[resource]:
        raw = params.get(key)
        if raw is None or raw == "":
            continue
        filters.append((key, _coerce(key, raw)))
    return filters


def to_sql(filters):
    clauses, args = [], []
    for key, value in filters:
        if key == "created_after":
            clauses.append("created_at > ?")
        else:
            clauses.append(f"{key} = ?")
        args.append(value)
    return (" AND ".join(clauses) or "1=1"), args


def build_query(resource, params):
    filters = collect_filters(params, resource)
    where, args = to_sql(filters)
    return f"SELECT * FROM {resource} WHERE {where}", args


def describe(filters):
    return ", ".join(f"{k}={v}" for k, v in filters) or "(no filters)"

