"""Lookup helpers over a time-ordered event list."""
from dataclasses import dataclass
from typing import Optional


@dataclass(frozen=True)
class Event:
    ts: float
    kind: str
    payload: dict


class Timeline:
    def __init__(self, events):
        self._events = sorted(events, key=lambda e: e.ts)

    def __len__(self):
        return len(self._events)

    def last_at_or_before(self, ts: float) -> Optional[Event]:
        """Return the latest event whose timestamp is <= ts, or None."""
        events = self._events
        lo, hi = 0, len(events) - 1
        best = None
        while lo <= hi:
            mid = (lo + hi) // 2
            if events[mid].ts <= ts:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return events[best] if best is not None else None

    def between(self, start: float, end: float):
        """Events with start <= ts < end."""
        i = self._lower_bound(start)
        out = []
        while i < len(self._events) and self._events[i].ts < end:
            out.append(self._events[i])
            i += 1
        return out

    def _lower_bound(self, ts):
        lo, hi = 0, len(self._events)
        while lo < hi:
            mid = (lo + hi) // 2
            if self._events[mid].ts < ts:
                lo = mid + 1
            else:
                hi = mid
        return lo

