"""Offset pagination for list endpoints (pages are 1-based in the public API)."""
from dataclasses import dataclass

DEFAULT_PAGE_SIZE = 25
MAX_PAGE_SIZE = 100
PAGINATED_TABLES = ("projects", "tickets", "comments")


class PageError(ValueError):
    pass


@dataclass
class Page:
    number: int
    size: int
    total: int

    @property
    def pages(self):
        return max(1, -(-self.total // self.size))

    @property
    def has_next(self):
        return self.number < self.pages


def parse_page(params):
    try:
        number = int(params.get("page", 1))
        size = int(params.get("per_page", DEFAULT_PAGE_SIZE))
    except (TypeError, ValueError):
        raise PageError("page and per_page must be integers") from None
    if number < 1:
        raise PageError("page must be >= 1")
    if not 1 <= size <= MAX_PAGE_SIZE:
        raise PageError(f"per_page must be between 1 and {MAX_PAGE_SIZE}")
    return number, size


def paginate(conn, table, params):
    if table not in PAGINATED_TABLES:
        raise PageError(f"{table} is not paginated")
    number, size = parse_page(params)
    total = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
    offset = number * size
    rows = conn.execute(
        f"SELECT * FROM {table} ORDER BY id LIMIT ? OFFSET ?", (size, offset)
    ).fetchall()
    return rows, Page(number, size, total)

