"""Retry helper with exponential backoff for flaky upstream calls."""
import logging
import random
import time

log = logging.getLogger(__name__)

RETRYABLE_STATUS = {429, 500, 502, 503, 504}


class RetryExhausted(Exception):
    def __init__(self, attempts, last_error):
        super().__init__(f"gave up after {attempts} attempts: {last_error}")
        self.attempts = attempts
        self.last_error = last_error


def backoff_delay(attempt, base=0.5, cap=30.0):
    delay = min(cap, base * (2 ** attempt))
    return delay * random.uniform(0.5, 1.0)


def call_with_retry(fn, *args, attempts=5, sleep=time.sleep, **kwargs):
    last_error = None
    for attempt in range(attempts):
        try:
            result = fn(*args, **kwargs)
        except ConnectionError as exc:
            last_error = exc
        else:
            status = getattr(result, "status_code", 200)
            if status not in RETRYABLE_STATUS:
                return result
            last_error = RuntimeError(f"upstream returned {status}")
        if attempt + 1 < attempts:
            wait = backoff_delay(attempt)
            log.warning(
                "attempt %d failed (%s); retrying in %.1fs", attempt + 1, last_error, wait
            )
            sleep(wait)
    raise RetryExhausted(attempts, last_error)

