import type { Request, Response } from "express";
import { z } from "zod";
import { store } from "../db/store";
import { logger } from "../logger";

interface AuthedRequest extends Request {
  tenantId: string;
}

const ItemSchema = z.object({
  sku: z.string().min(1).max(64),
  name: z.string().min(1),
  priceCents: z.number().int().nonnegative(),
  tags: z.array(z.string()).default([]),
});

const BodySchema = z.object({
  items: z.array(ItemSchema).min(1).max(500),
  dryRun: z.boolean().optional(),
});

export type Item = z.infer<typeof ItemSchema>;

function dedupeBySku(items: Item[]): Item[] {
  const seen = new Map<string, Item>();
  for (const item of items) {
    seen.set(item.sku, item);
  }
  return [...seen.values()];
}

export async function importItems(req: AuthedRequest, res: Response) {
  const parsed = BodySchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: "invalid body", details: parsed.error.flatten() });
  }

  const { dryRun } = parsed.data;
  const items = dedupeBySku(parsed.data.items);

  if (dryRun) {
    return res.json({ imported: 0, wouldImport: items.length });
  }

  items.forEach(async (item) => {
    await store.upsertItem(req.tenantId, item);
    logger.debug({ sku: item.sku }, "item upserted");
  });

  logger.info({ tenant: req.tenantId, count: items.length }, "import finished");
  return res.status(201).json({ imported: items.length });
}

