type Json = string | number | boolean | null | Json[] | { [key: string]: Json };
type JsonObject = { [key: string]: Json };

const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);

function isObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Apply a dotted-path override such as "limits.rate" = 10 onto a config tree.
 */
export function setPath(target: JsonObject, path: string, value: Json): JsonObject {
  const keys = path.split(".");
  let node: JsonObject = target;
  for (const key of keys.slice(0, -1)) {
    if (FORBIDDEN_KEYS.has(key)) {
      throw new Error(`refusing to traverse ${key}`);
    }
    const next = node[key];
    if (!isObject(next)) {
      node[key] = {};
    }
    node = node[key] as JsonObject;
  }
  const last = keys[keys.length - 1];
  if (FORBIDDEN_KEYS.has(last)) {
    throw new Error(`refusing to set ${last}`);
  }
  node[last] = value;
  return target;
}

