export interface LimiterOptions {
  limit: number;
  maxQueue?: number;
}

export class QueueFullError extends Error {
  constructor() {
    super("limiter queue is full");
    this.name = "QueueFullError";
  }
}

/**
 * Bounds the number of in-flight upstream calls made by this process.
 * Used from request handlers on the main event loop only.
 */
export class ConcurrencyLimiter {
  private inflight = 0;
  private readonly waiters: Array<() => void> = [];
  private readonly limit: number;
  private readonly maxQueue: number;

  constructor(opts: LimiterOptions) {
    this.limit = opts.limit;
    this.maxQueue = opts.maxQueue ?? 100;
  }

  tryAcquire(): boolean {
    if (this.inflight >= this.limit) {
      return false;
    }
    this.inflight += 1;
    return true;
  }

  async acquire(): Promise<void> {
    if (this.tryAcquire()) {
      return;
    }
    if (this.waiters.length >= this.maxQueue) {
      throw new QueueFullError();
    }
    await new Promise<void>((resolve) => this.waiters.push(resolve));
  }

  release(): void {
    const next = this.waiters.shift();
    if (next) {
      // hand the slot straight to the next waiter; inflight stays the same
      next();
      return;
    }
    this.inflight -= 1;
  }

  async run<T>(fn: () => Promise<T>): Promise<T> {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }

  get stats() {
    return { inflight: this.inflight, queued: this.waiters.length };
  }
}

