export class TimeoutError extends Error {
  constructor(url: string, ms: number) {
    super(`request to ${url} timed out after ${ms}ms`);
    this.name = "TimeoutError";
  }
}

export interface RetryOptions {
  retries?: number;
  timeoutMs?: number;
  retryOn?: number[];
}

const DEFAULTS: Required<RetryOptions> = {
  retries: 2,
  timeoutMs: 8000,
  retryOn: [502, 503, 504],
};

async function once(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } catch (err) {
    if (controller.signal.aborted) {
      throw new TimeoutError(url, timeoutMs);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

export async function fetchWithRetry(
  url: string,
  init: RequestInit = {},
  options: RetryOptions = {},
): Promise<Response> {
  const { retries, timeoutMs, retryOn } = { ...DEFAULTS, ...options };
  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await once(url, init, timeoutMs);
      if (!retryOn.includes(res.status) || attempt === retries) {
        return res;
      }
      lastError = new Error(`upstream status ${res.status}`);
    } catch (err) {
      lastError = err;
      if (!(err instanceof TimeoutError) && !(err instanceof TypeError)) {
        throw err;
      }
    }
    await new Promise((resolve) => setTimeout(resolve, 250 * 2 ** attempt));
  }
  throw lastError;
}

