export interface ScoreEntry {
  playerId: string;
  scores: number[];
}

export interface Ranked {
  playerId: string;
  best: number;
  median: number;
  rank: number;
}

function median(values: number[]): number {
  if (values.length === 0) {
    return 0;
  }
  const sorted = values.slice().sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
}

export function topScores(scores: number[], n: number): number[] {
  const sorted = scores.sort().reverse();
  return sorted.slice(0, n);
}

export function rankPlayers(entries: ScoreEntry[]): Ranked[] {
  const rows = entries
    .filter((e) => e.scores.length > 0)
    .map((e) => ({
      playerId: e.playerId,
      best: Math.max(...e.scores),
      median: median(e.scores),
    }));

  rows.sort(
    (a, b) => b.best - a.best || b.median - a.median || a.playerId.localeCompare(b.playerId),
  );

  return rows.map((row, i) => ({ ...row, rank: i + 1 }));
}

export function percentile(values: number[], p: number): number {
  if (values.length === 0) {
    throw new RangeError("percentile of empty list");
  }
  const sorted = [...values].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.ceil((p / 100) * sorted.length) - 1);
  return sorted[Math.max(0, idx)];
}

