import type { NextFunction, Request, Response } from "express";
import { redis } from "../redis";

interface Options {
  windowSec: number;
  max: number;
  keyPrefix?: string;
}

interface UserRequest extends Request {
  user?: { id: string };
}

export function rateLimit({ windowSec, max, keyPrefix = "rl" }: Options) {
  return async (req: UserRequest, res: Response, next: NextFunction) => {
    const identity = req.user?.id ?? req.ip;
    const bucket = Math.floor(Date.now() / (windowSec * 1000));
    const key = `${keyPrefix}:${identity}:${bucket}`;

    let count: number;
    try {
      count = await redis.incr(key);
      if (count === 1) {
        await redis.expire(key, windowSec);
      }
    } catch (err) {
      console.warn("rate limiter unavailable, allowing request", err);
      return next();
    }

    res.setHeader("X-RateLimit-Limit", String(max));
    res.setHeader("X-RateLimit-Remaining", String(Math.max(0, max - count)));

    if (count > max) {
      res.setHeader("Retry-After", String(windowSec));
      return res.status(429).json({ error: "rate limit exceeded" });
    }
    return next();
  };
}

export function resetLimit(keyPrefix: string, identity: string, windowSec: number) {
  const bucket = Math.floor(Date.now() / (windowSec * 1000));
  return redis.del(`${keyPrefix}:${identity}:${bucket}`);
}

