// Manifest maps file paths to their hex-encoded SHA-256 digest.
type Manifest map[string]string

// Build hashes every path and returns a manifest. Unreadable files abort the
// whole run so a partial manifest is never written.
func Build(paths []string) (Manifest, error) {
	m := make(Manifest, len(paths))
	for _, p := range paths {
		f, err := os.Open(p)
		if err != nil {
			return nil, fmt.Errorf("open %s: %w", p, err)
		}
		defer f.Close()

		h := sha256.New()
		if _, err := io.Copy(h, f); err != nil {
			return nil, fmt.Errorf("hash %s: %w", p, err)
		}
		m[p] = hex.EncodeToString(h.Sum(nil))
	}
	return m, nil
}

// Verify re-hashes the files listed in want and returns the paths whose
// digest differs or that no longer exist.
func Verify(want Manifest) ([]string, error) {
	var bad []string
	for p, digest := range want {
		got, err := hashFile(p)
		if os.IsNotExist(err) {
			bad = append(bad, p)
			continue
		}
		if err != nil {
			return nil, err
		}
		if got != digest {
			bad = append(bad, p)
		}
	}
	sort.Strings(bad)
	return bad, nil
}

func hashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

