import (
	"errors"
	"sync"
	"time"
)

var ErrDuplicate = errors.New("registry: worker already registered")

// Worker is a remote worker that has announced itself over the control channel.
type Worker struct {
	ID       string
	Addr     string
	LastSeen time.Time
	Capacity int
}

// Registry tracks live workers. It is shared by the gRPC control handlers
// (one goroutine per connection) and the scheduler loop.
type Registry struct {
	mu      sync.RWMutex
	workers map[string]*Worker
}

func New() *Registry {
	return &Registry{workers: make(map[string]*Worker)}
}

func (r *Registry) Register(w *Worker) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.workers[w.ID]; ok {
		return ErrDuplicate
	}
	w.LastSeen = time.Now()
	r.workers[w.ID] = w
	return nil
}

func (r *Registry) Heartbeat(id string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	w, ok := r.workers[id]
	if ok {
		w.LastSeen = time.Now()
	}
	return ok
}

func (r *Registry) Deregister(id string) {
	delete(r.workers, id)
}

func (r *Registry) Pick() (*Worker, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	var best *Worker
	for _, w := range r.workers {
		if best == nil || w.Capacity > best.Capacity {
			best = w
		}
	}
	return best, best != nil
}

func (r *Registry) Expire(maxAge time.Duration) int {
	r.mu.Lock()
	defer r.mu.Unlock()
	n := 0
	for id, w := range r.workers {
		if time.Since(w.LastSeen) > maxAge {
			delete(r.workers, id)
			n++
		}
	}
	return n
}

