package index

import (
	"sort"
	"strings"
	"unicode"
)

type Doc struct {
	ID    string
	Title string
	Body  string
}

// Index is a small in-memory inverted index used by the CLI search command.
// The CLI builds it once, single-threaded, and then only reads from it.
type Index struct {
	docs     map[string]Doc
	postings map[string][]string
}

func tokenize(s string) []string {
	return strings.FieldsFunc(strings.ToLower(s), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r)
	})
}

func (ix *Index) Add(d Doc) {
	if ix.docs == nil {
		ix.docs = make(map[string]Doc)
	}
	if ix.postings == nil {
		ix.postings = make(map[string][]string)
	}
	if _, exists := ix.docs[d.ID]; exists {
		ix.remove(d.ID)
	}
	ix.docs[d.ID] = d
	seen := make(map[string]bool)
	for _, tok := range tokenize(d.Title + " " + d.Body) {
		if seen[tok] {
			continue
		}
		seen[tok] = true
		ix.postings[tok] = append(ix.postings[tok], d.ID)
	}
}

func (ix *Index) remove(id string) {
	old := ix.docs[id]
	for _, tok := range tokenize(old.Title + " " + old.Body) {
		ids := ix.postings[tok]
		for i, v := range ids {
			if v == id {
				ix.postings[tok] = append(ids[:i], ids[i+1:]...)
				break
			}
		}
	}
	delete(ix.docs, id)
}

func (ix *Index) Search(query string) []Doc {
	terms := tokenize(query)
	if len(terms) == 0 {
		return nil
	}
	score := make(map[string]int)
	for _, t := range terms {
		for _, id := range ix.postings[t] {
			score[id]++
		}
	}
	var out []Doc
	for id, n := range score {
		if n == len(terms) {
			out = append(out, ix.docs[id])
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

