-- 0042_archive_function.sql
-- Helper used by the retention job to move old rows into <table>_archive.

BEGIN;

CREATE OR REPLACE FUNCTION archive_old_rows(
    p_table   text,
    p_before  timestamptz,
    p_batch   integer DEFAULT 5000
) RETURNS bigint
LANGUAGE plpgsql
AS $$
DECLARE
    v_moved bigint := 0;
    v_batch bigint;
BEGIN
    IF p_table NOT IN ('events', 'audit_log', 'webhook_deliveries') THEN
        RAISE EXCEPTION 'table % is not archivable', p_table
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    IF p_batch < 1 OR p_batch > 50000 THEN
        RAISE EXCEPTION 'batch size out of range: %', p_batch;
    END IF;

    LOOP
        EXECUTE format(
            'WITH moved AS (
                 DELETE FROM %1$I
                 WHERE ctid IN (
                     SELECT ctid FROM %1$I
                     WHERE created_at < $1
                     ORDER BY created_at
                     LIMIT $2
                     FOR UPDATE SKIP LOCKED
                 )
                 RETURNING *
             )
             INSERT INTO %2$I SELECT * FROM moved',
            p_table, p_table || '_archive'
        ) USING p_before, p_batch;

        GET DIAGNOSTICS v_batch = ROW_COUNT;
        EXIT WHEN v_batch = 0;
        v_moved := v_moved + v_batch;
    END LOOP;

    RETURN v_moved;
END;
$$;

REVOKE ALL ON FUNCTION archive_old_rows(text, timestamptz, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION archive_old_rows(text, timestamptz, integer) TO retention_job;

